export function localizeEntries(entries) {
 for(const item of entries){
  if(item.title.en && item.title.es) continue;
  const row=E[item.id]; if(!row) throw new Error(`Missing editorial translations: ${item.id}`);
  ['title','summary','body','tips'].forEach((key,i)=>Object.assign(item[key],row[i]));
  item.attractions=row[4].map((value,i)=>({...item.attractions[i],...value}));
 }
}
