export function localizeSupporting({photos,sources,timeline,routes}){
 for(const p of photos)Object.assign(p.title,P[p.id]);
 for(const [id,value] of Object.entries(sources))if(S[id])Object.assign(value.description,S[id]);
 timeline.forEach((item,i)=>{item.yearLabel={fr:item.year,ar:item.arYear||item.year,...T[i][0]};['tag','title','body'].forEach((key,k)=>Object.assign(item[key],T[i][k+1]));});
 for(const route of routes)['title','category','duration','summary','tip'].forEach((key,i)=>Object.assign(route[key],R[route.id][i]));
}
